package main

import "fmt"

type Counter struct {
	n int
}

// Value receiver: operates on a COPY, so the mutation is lost.
func (c Counter) IncValue() {
	c.n++ // changes the copy only
}

// Pointer receiver: operates on the ORIGINAL via its address.
func (c *Counter) IncPointer() {
	c.n++ // changes the real Counter
}

func main() {
	c := Counter{}

	c.IncValue() // copy is incremented then discarded
	fmt.Println("after IncValue:", c.n)

	c.IncPointer() // c is addressable, so Go calls (&c).IncPointer()
	fmt.Println("after IncPointer:", c.n)

	// Calling a pointer method through an explicit pointer also works.
	p := &c
	p.IncPointer()
	fmt.Println("after p.IncPointer:", c.n)
}

package main

import "fmt"

type Stringer interface {
	String() string
}

type Temp struct {
	celsius float64
}

// Pointer receiver, so String() is only in *Temp's method set.
func (t *Temp) String() string {
	return fmt.Sprintf("%.1f°C", t.celsius)
}

func main() {
	t := Temp{celsius: 21.5}

	// Direct call compiles: t is addressable, Go uses (&t).String().
	fmt.Println(t.String())

	// Assigning to the interface uses the STRICT method set.
	var s Stringer = &t // OK: *Temp has String()
	fmt.Println(s.String())

	// var bad Stringer = t // COMPILE ERROR:
	// Temp does not implement Stringer (String has pointer receiver)

	// A Temp stored in a map is not addressable, so even t.String() style
	// access would fail there for a pointer-receiver method.
	m := map[string]*Temp{"room": &t}
	fmt.Println(m["room"].String())
}

package main

import "fmt"

// Methods can be defined on any named type, not just structs.
type Celsius float64

func (c Celsius) Fahrenheit() float64 {
	return float64(c)*9/5 + 32
}

func main() {
	boiling := Celsius(100)

	// Method value: receiver is bound NOW to `boiling`.
	f := boiling.Fahrenheit // type: func() float64
	fmt.Println("method value:", f())

	// Method expression: receiver is an explicit first parameter.
	g := Celsius.Fahrenheit // type: func(Celsius) float64
	fmt.Println("method expression:", g(Celsius(0)))
	fmt.Println("method expression:", g(boiling))
}
